package com.legitimateapps.dulcet.server.discover

import com.legitimateapps.dulcet.server.v1.*
import kotlinx.serialization.json.*

fun availabilityJson(a:Availability)=JsonObject(j("status" to a.status,"libraryItems" to a.libraryItems.map { j("id" to it.id,"type" to it.type) },"matchedBy" to a.matchedBy,"matchedTrackCount" to a.matchedTrackCount,"totalTrackCount" to a.totalTrackCount,"editionReleaseId" to a.editionReleaseId,"completeness" to a.completeness).filterValues { it!=JsonNull })
fun itemJson(item:DiscoverItem):JsonObject=JsonObject(j("id" to item.id,"kind" to item.kind.wire,"title" to item.title,"artist" to item.artist,"year" to item.year,"releaseDate" to item.releaseDate,"externalIds" to item.externalIds,"artworkId" to item.artworkId,"links" to item.links.map { j("relation" to it.relation,"url" to it.url) },"wishable" to item.wishable,"availability" to availabilityJson(item.availability),"disc" to item.disc,"position" to item.position,"listenCount" to item.listenCount,"artistMbids" to item.artistMbids,"primaryType" to item.primaryType).filterValues { it!=JsonNull })
internal fun readItem(o:JsonObject)=DiscoverItem(id=o.text("id").orEmpty(),kind=DiscoverKind.parse(o.requiredText("kind")),title=o.requiredText("title"),artist=o.text("artist"),year=o.text("year")?.toIntOrNull(),releaseDate=o.text("releaseDate"),externalIds=o["externalIds"]!!.jsonObject.mapValues { it.value.jsonPrimitive.content },artworkId=o.text("artworkId"),links=o.rows("links").map { ExternalLink(it.obj().requiredText("relation"),it.obj().requiredText("url")) },wishable=o["wishable"]!!.jsonPrimitive.boolean,disc=o.text("disc")?.toIntOrNull(),position=o.text("position")?.toIntOrNull(),listenCount=o.text("listenCount")?.toLongOrNull(),artistMbids=(o["artistMbids"] as? JsonArray).orEmpty().map { it.jsonPrimitive.content },primaryType=o.text("primaryType"))
fun summaryJson(s:PlaylistSummary)=j("id" to s.id,"title" to s.title,"creator" to s.creator,"trackCount" to s.trackCount)
internal fun readSummary(o:JsonObject)=PlaylistSummary(o.requiredText("id"),o.requiredText("title"),o.text("creator"),o.text("trackCount")?.toIntOrNull())
fun <T> pageJson(page:DiscoverPage<T>,encode:(T)->JsonElement)=j("items" to page.items.map(encode),"nextCursor" to page.nextCursor,"fetchedAt" to iso(page.age.fetchedAt),"ageSeconds" to page.age.ageSeconds,"stale" to page.age.stale)
fun artistJson(page:DiscoverArtistPage)=j("item" to itemJson(page.item),"albums" to pageJson(page.albums,::itemJson))
fun albumJson(page:DiscoverAlbumPage)=j("item" to itemJson(page.item),"editions" to page.editions.map { j("releaseId" to it.releaseMbid,"releaseDate" to it.releaseDate,"trackCount" to it.tracks.size,"links" to it.links.map { l -> j("relation" to l.relation,"url" to l.url) }) },"selectedReleaseId" to page.selectedReleaseId,"tracks" to pageJson(page.tracks,::itemJson))
fun playlistJson(page:DiscoverPlaylistPage)=j("summary" to summaryJson(page.summary),"entries" to pageJson(page.entries) { j("position" to it.position,"item" to itemJson(it.item)) })
